"""Regenerate static pages from the shipped pack archive; standard library only."""
from pathlib import Path
import re, json, zipfile, html, sys
ROOT = Path(__file__).resolve().parents[1]
DISCORD = 'https://discord.com/channels/659137486332887071/1054946454545907762'
def esc(value): return html.escape(str(value), quote=True)
def page(file, title, body, hero=False):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if file==url or (url=='mods.html' and file in ('auto-close-doors.html','progression-bridge.html','backpack-balance.html')) else '')+f'>{name}</a>' for url,name in [('index.html','Overview'),('install.html','Install'),('mods.html','Mods'),('keybindings.html','Default Keybindings'),('changelog.html','Changelog')])
    markup = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="True Bastards Valheim: a survival mod pack for friends. Installation, included mods and release notes."><title>{esc(title)} · True Bastards Valheim</title><link rel="stylesheet" href="assets/style.css"></head>
<body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="index.html">TRUE BASTARDS <span>/ VALHEIM</span></a><nav aria-label="Main navigation">{nav}<a href="{DISCORD}">Discord ↗</a></nav></header>
{body if hero else '<main id="main">'+body+'</main>'}
<footer><p>True Bastards · Valheim</p><p><a href="{DISCORD}">Downloads &amp; server details on Discord ↗</a></p></footer>
{'<script src="assets/mods.js"></script>' if file=='mods.html' else ''}</body></html>'''
    (ROOT/file).write_text(markup,encoding='utf-8')

page('index.html','Overview',f'''<div class="hero"><div class="eyebrow">A Valheim survival pack</div><h1>A place to build.<br>A reason to venture out.</h1><p>Familiar survival, more equipment to discover, and fewer fiddly chores. Built for the True Bastards crew.</p><div class="actions"><a class="button" href="install.html">Get ready to join →</a><a class="button secondary" href="mods.html">Explore the mods</a></div></div>
<main id="main"><div class="eyebrow">Our kind of Valheim</div><h2>Keep the adventure. Smooth the rough edges.</h2><p class="intro">Gather supplies, haul them home, build something worth defending and head out together. This pack stays close to the rhythm of Valheim, with extra loot, weapons and quality-of-life features along the way.</p>
<div class="grid"><section class="card"><span class="number">01 / EXPLORE</span><h3>Make the journey count.</h3><p>Backpacks, a hip lantern and travel improvements help on longer trips. Gathering resources and getting them home still matter.</p></section><section class="card"><span class="number">02 / FIGHT</span><h3>Find your next favourite.</h3><p>Epic Loot, new weapons and armour, and enemies with extra stars and modifiers give you more to discover and prepare for.</p></section><section class="card"><span class="number">03 / SETTLE</span><h3>Build a proper home.</h3><p>Better building controls, easier repairs, planting tools and clearer item information make the everyday work more comfortable.</p></section></div>
<div class="split"><section><h2>Progress at your own pace.</h2><p class="muted">Boss progression is tracked per character. Someone else defeating a boss does not automatically give your character the same unlocks. Some equipment and activities stay locked until you earn the required progress.</p><p class="muted">Joining with an older character? Tell us in Discord if you have already beaten bosses but your gear is being rejected.</p></section><section class="card"><div class="eyebrow">Before you sail</div><h3>One shared pack.</h3><p>Use the version posted in our Valheim Discord channel so your mods and settings match the server.</p><a href="{DISCORD}">Open the Valheim channel ↗</a></section></div>
<section class="band"><h2>September 26 · Latest test update</h2><p>New stamina improvements, better-balanced backpacks, extra food and gentler creature scaling. Check Discord for the version currently running on the server before updating.</p><a href="changelog.html">Read the release notes →</a></section></main>''',True)

page('install.html','Installation',f'''<div class="eyebrow">Join the crew</div><h1 class="page-title">Get ready to join.</h1><p class="intro">Get the pack and server address from our <a href="{DISCORD}">Valheim Discord channel</a>. You need access to the True Bastards Discord to open it. Always use the version announced for the server.</p>
<section class="band"><h2>September 26 test pack</h2><p>The latest prepared client bundle is <code>TBValheim_Next_Test.zip</code>. It is a full pack, not an update-only ZIP. Install it when the server announcement asks you to. The server ZIP is for the server owner.</p><p><a href="changelog.html#september-26">See what changed →</a></p></section>
<section id="update"><h2>Updating an existing installation</h2><ol class="steps"><li><strong>Before updating, unequip the Atlantean Crown if you use it.</strong><p>Vikings Do Swim is being removed, including its diving feature and crown.</p></li><li><strong>Close Valheim and extract the client ZIP.</strong><p>In Steam, right-click Valheim → Manage → Browse local files. Keep a backup of any personal mod settings you want to restore.</p></li><li><strong>Copy the extracted contents beside valheim.exe.</strong><p>Merge folders and replace matching files. The supplied BepInEx folder belongs beside valheim.exe, not inside another BepInEx folder.</p></li><li><strong>Run Remove Old Mods.bat from that game folder.</strong><p>This moves the retired Need for Speed, Reely Good Rod, Vikings Do Swim and Comfy Auto Repair files into a backup folder under <code>TBPack-Removed-Mods</code>. Leave that backup outside BepInEx. Wait for the script to finish successfully before starting the game.</p></li><li><strong>Launch through Steam and join.</strong><p>Keep your pack aligned with the server. Check your personal shortcuts and door preferences after updating.</p></li></ol><p>The cleanup list is carried forward in future packs, so players who skip an update can still remove older retired mods. Always run the script supplied with the latest full pack; copying new files alone does not remove old mods.</p></section>
<section><h2>Installing for the first time</h2><ol class="steps"><li><strong>Install Valheim through Steam and launch it once.</strong><p>Close it before installing the pack.</p></li><li><strong>Download and extract the full client ZIP announced in Discord.</strong><p>Use a clean game installation without unrelated mods.</p></li><li><strong>Open Steam → Valheim → Manage → Browse local files.</strong><p>Copy the extracted contents into this folder. BepInEx, winhttp.dll and doorstop_config.ini should sit beside valheim.exe.</p></li><li><strong>Launch through Steam.</strong><p>Let the mods finish loading, then use the server details in Discord.</p></li></ol></section>
<div class="split"><section class="card"><h3>Controls and personal settings</h3><p>Press F1 for mod settings. Some settings are controlled by the server; personal controls can be changed where the mod allows it.</p><a href="keybindings.html">Default Keybindings →</a></section><section class="card" id="door-settings"><h3>Your doors, your timer</h3><p>After joining, open F1 → TrueBastards Auto Close Doors → 2 - My doors. Choose ServerDefault, CustomTimer or NeverClose.</p><a href="auto-close-doors.html">Door settings guide →</a></section></div>
<section class="band"><h2>Something isn’t right?</h2><p>Tell us what happened, which pack you installed and any error message. If an older character sees “The Gods Reject You”, mention which bosses you have already defeated. If the cleanup script stops with an error, share that message before launching.</p><a href="{DISCORD}">Get help in Discord ↗</a></section>''')

descriptions = {
'PlantEverything':('Building & home','Plant Everything','More planting options for gardens and the land around your base.'),
'SeedBed':('Building & home','Seed Bed','Adds seed beds for your farming setup.'),
'VikingsDoSwim':('Travel & utility','Vikings Do Swim','Expands swimming controls, including diving.'),
'SearsCatalog':('Building & home','Sears Catalog','Makes larger building menus easier to browse.'),
'Pathfinder':('Travel & utility','Pathfinder','Adjusts exploration and map discovery.'),
'Better_Wisps':('Travel & utility','Better Wisps','Improves the usefulness of wisps in the mist.'),
'Digitalroots_Slope_Combat_Assistance':('Combat & equipment','Slope Combat Assistance','Helps melee attacks connect when fighting on slopes.'),
'Max_Dungeon_Rooms':('Combat & equipment','Max Dungeon Rooms','Changes dungeon room limits for dungeon generation.'),
'Blacksmiths_tools':('Libraries & support','Blacksmith’s Tools','Support tools used by Jude’s equipment mods.'),
'Judes_Equipment':('Combat & equipment','Jude’s Equipment','Adds more equipment to discover and craft.'),
'ValheimArmory':('Combat & equipment','Valheim Armory','More weapon choices across your adventure.'),
'EpicLoot':('Combat & equipment','Epic Loot','Adds magical equipment, enchantments and loot to hunt for.'),
'HipLantern':('Travel & utility','Hip Lantern','A wearable light with a separate heat mode.'),
'TradersExtended':('Travel & utility','Traders Extended','Expands trader interactions, including equipment repairs.'),
'AdventureBackpacks':('Travel & utility','Adventure Backpacks','Adds wearable backpacks and associated utility features.'),
'Venture_Area_Repair':('Building & home','Venture Area Repair','Makes repairing nearby building pieces less repetitive.'),
'Venture_Farm_Grid':('Building & home','Venture Farm Grid','Helps arrange crops with consistent spacing.'),
'Venture_Floating_Items':('Travel & utility','Venture Floating Items','Makes dropped items float so they are easier to recover from water.'),
'Venture_Logout_Tweaks':('Travel & utility','Venture Logout Tweaks','Adjusts logout behaviour.'),
'Daywheel':('Travel & utility','Daywheel','Adds an at-a-glance display of the day’s progress.'),
'Reely_Good_Rod':('Travel & utility','Reely Good Rod','Quality-of-life adjustments for fishing.'),
'Warm_Torches':('Travel & utility','Warm Torches','Adds warmth to carried torches.'),
'EpicLoot_ProgressionFix':('Progression','Epic Loot Progression Fix','Compatibility fixes for Epic Loot progression.'),
'World_Advancement_Progression':('Progression','World Advancement Progression','Tracks individual progress and gates equipment and activities behind boss kills.'),
'Need_For_Speed':('Travel & utility','Need for Speed','Makes travel along prepared paths more useful.'),
'AdvancedPortals':('Travel & utility','Advanced Portals','Adds portal tiers with different transport capabilities.'),
'StarLevelSystem':('Combat & equipment','Star Level System','Adds configurable creature stars, modifiers and raids.'),
'ZenSign':('Building & home','ZenSign','More useful signs for organising your base.'),
'ZenHoverItem':('Travel & utility','ZenHoverItem','Clearer information about items, containers and fuel when you look at them.'),
'ZenDistributor':('Building & home','ZenDistributor','Cart and distribution conveniences. The pack does not use its cart weight assistance.'),
'ZenBeehive':('Building & home','ZenBeehive','Easier manual collection from beehives.'),
'ZenRedecorate':('Building & home','ZenRedecorate','Move placed objects when rearranging your base.'),
'ZenConstruction':('Building & home','ZenConstruction','Building controls and nearby-container conveniences, with vanilla structural rules retained.'),
'BepInExPack_Valheim':('Libraries & support','BepInExPack Valheim','The loader that runs the pack’s mods.'),
'Jotunn':('Libraries & support','Jötunn','Shared support for custom items, building pieces and other mod features.'),
'JsonDotNET':('Libraries & support','Json.NET','A shared data library required by other mods.'),
'YamlDotNet':('Libraries & support','YamlDotNet','A shared configuration library required by other mods.'),
'ConditionalConfigSync':('Libraries & support','Conditional Config Sync','Supports synchronising mod settings.'),
'ConfigurationManager':('Libraries & support','Configuration Manager','An in-game interface for changing mod settings.'),
'Zen_ModLib':('Libraries & support','Zen ModLib','Shared support for the installed Zen mods.')}

if len(sys.argv)>1:
    archive=Path(sys.argv[1])
    with zipfile.ZipFile(archive) as z:
        raw=z.read('mods.yml').decode('utf-8-sig')
        mods=[]
        for block in re.split(r'^- manifestVersion:',raw,flags=re.M)[1:]:
            if not re.search(r'^  enabled: true$',block,re.M): continue
            full=re.search(r'^  name: (.+)$',block,re.M)[1].strip()
            author,name=full.split('-',1)
            cat,label,desc=descriptions[name]
            version='.'.join(re.search(r'^    '+part+r': (\d+)$',block,re.M)[1] for part in ['major','minor','patch'])
            mods.append(dict(name=label,category=cat,description=desc,version=version,url=f'https://thunderstore.io/c/valheim/p/{author}/{name}/'))
        assert any('TrueBastards.ProgressionBridge.dll' in n for n in z.namelist())
    (ROOT/'mods.json').write_text(json.dumps(mods,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
else:
    mods=json.loads((ROOT/'mods.json').read_text(encoding='utf-8'))
cards=''
for mod in sorted(mods,key=lambda x:(x['category'],x['name'].lower())):
    cards+=f'''<article class="card mod" data-mod data-category="{esc(mod['category'])}"><div class="meta">{esc(mod['category'])} · {esc(mod['version'])}</div><h2>{esc(mod['name'])}</h2><p>{esc(mod['description'])}</p><a href="{esc(mod['url'])}">View on Thunderstore ↗</a></article>'''
categories=''.join(f'<option>{esc(c)}</option>' for c in sorted({m['category'] for m in mods}))
page('mods.html','Included mods',f'''<div class="eyebrow">The pack, piece by piece</div><h1 class="page-title">What’s on board.</h1><p class="intro">The mods in the September 26 test pack, with links to their own pages. Check Discord before updating to match the server. Our pack settings may differ from a mod’s defaults. Use the Discord download to get the complete setup.</p><div class="filters"><label>Search mods<input id="search" type="search" placeholder="Try building, loot or backpacks…"></label><label>Category<select id="category"><option value="">All categories</option>{categories}</select></label></div><p id="count" class="muted" role="status">{len(mods)} mods</p><p id="empty" hidden>No matches. Try another search or category.</p><div class="mod-grid">{cards}</div><section class="band"><h2>Made for this pack</h2><p><a href="auto-close-doors.html"><strong>Auto Close Doors 0.2.1 →</strong></a><br>Automatic closing for player-built doors and gates, with personal timers.</p><p><a href="progression-bridge.html"><strong>Progression Bridge 0.1.1 →</strong></a><br>Connects Star Level System raid checks to individual boss progression.</p><p><a href="backpack-balance.html"><strong>Backpack Balance 0.1.2 →</strong></a><br>Cape-matched durability and armour for Jude’s Simple and Heavy Backpacks.</p><p>Included with the pack. Each has its own guide here rather than a Thunderstore listing.</p></section>''')

page('changelog.html','Changelog','''<div class="eyebrow">The captain’s log</div><h1 class="page-title">What’s changed.</h1><p class="intro">Pack releases and the changes that matter when you play. Download the current version from our Valheim Discord channel.</p><article class="release" id="september-26"><div class="eyebrow">26 September 2026 · Test update</div><h2>A smoother journey, a fairer fight.</h2><p>This update is prepared for server testing. Use the pack announced in Discord; these notes do not mean the server has already switched.</p><h3>New additions</h3><ul><li><strong>Stamina Extended</strong> brings together stamina, swimming, fishing and terrain travel adjustments. Fishing pull stamina is set to half its usual cost.</li><li><strong>Simple Compass</strong> adds direction and map-pin guidance.</li><li><strong>Jam and HoneyPlus</strong> add food choices and beekeeping options.</li><li><strong>Loot Filter</strong> lets you choose items to exclude from automatic pickup. Its blacklist starts empty.</li></ul><h3>Balance and fixes</h3><ul><li><strong>Creature stars:</strong> reduced the influence of distance and local kills, removed the extra night boost and made local difficulty decay faster. Biomes and distance still matter, and raids still contribute kills. This aims for a gentler spread; it does not guarantee zero-star spawns everywhere.</li><li><strong>Raids:</strong> doubled the per-player cooldown scaling. Raid checks still use the mod’s per-player system.</li><li><strong>Backpack Balance:</strong> Jude’s Simple Backpack now matches Deer Hide Cape durability and armour; the Heavy Backpack matches Troll Hide Cape. Carry bonuses remain unchanged. <a href="backpack-balance.html">Read the guide →</a></li><li><strong>Progression Bridge:</strong> updated for Star Level System 1.19.0, keeping raid eligibility linked to each character’s boss progress.</li><li><strong>Adventure Backpacks:</strong> updated backpack automation settings, keeping crafting and automatic storage enabled. Crafting uses your main inventory first and leaves one item in a backpack stack.</li></ul><h3>Repair hotfix</h3><p>Removed Comfy Auto Repair after reports of incomplete repairs and an unavailable manual repair button. Use the normal repair button at the appropriate station. The latest cleanup script removes it from existing installations.</p><p>Backpack Balance 0.1.2 fixes Jude’s backpack stats being reset during world loading. Restart after installing and repair your backpack to fill its new durability.</p><h3>Replaced mods — cleanup required</h3><p>Stamina Extended replaces <strong>Need for Speed, Reely Good Rod and Vikings Do Swim</strong>. Diving and the Atlantean Crown are no longer included. Unequip the crown before updating and run the supplied <strong>Remove Old Mods.bat</strong> after copying the client pack.</p><p><a href="install.html#update">Follow the full update steps →</a> · <a href="keybindings.html">Check the default controls →</a></p><details><summary>Updated mod versions</summary><ul><li>Plant Everything 1.21.3</li><li>Max Dungeon Rooms 2.0.40</li><li>Star Level System 1.19.0</li><li>Epic Loot Progression Fix 0.1.75</li><li>Adventure Backpacks 2.2.0</li><li>Daywheel 1.0.13</li><li>Zen ModLib 1.14.16</li><li>TrueBastards Progression Bridge 0.1.1</li><li>TrueBastards Backpack Balance 0.1.2</li></ul></details></article><article class="release" id="release-1-0-1"><div class="eyebrow">25 September 2026 · Pack update</div><h2>1.0.1 — A closer view, doors your way</h2><ul><li>Added <strong>First Person 1.0.13</strong>. Press F6 to toggle the camera view.</li><li>Added <strong>TrueBastards Auto Close Doors 0.2.1</strong> for player-built doors and gates, including wooden gates.</li><li>Each builder can choose a custom timer, the server default or NeverClose in F1. Personal settings do not require admin rights and are saved by the server.</li><li>The included door mod fixes the preference-handshake issue in the earlier test build. Dungeon doors and generated-building doors remain excluded.</li></ul><p><strong>Historical 1.0 → 1.0.1 downloads:</strong> <code>TBValheim_Update_1.0_to_1.0.1.zip</code> from Discord. The full release was <code>TBValheim_1.0.1.zip</code>. Use Discord for the current server pack.</p><p><a href="install.html#update">Follow the update steps →</a> · <a href="install.html#door-settings">Choose your door settings →</a></p></article><article class="release" id="release-1-0"><div class="eyebrow">24 September 2026 · Initial release</div><h2>1.0 — Ready to set sail</h2><ul><li>Added Epic Loot, Valheim Armory and Jude’s Equipment for more loot and equipment choices.</li><li>Added Star Level System for creature stars, modifiers and raids.</li><li>Introduced individual boss progression through World Advancement Progression, with the pack’s progression bridge included.</li><li>Added building, farming, repair, storage and travel conveniences, including backpacks and a hip lantern.</li><li>Kept vanilla building support rules and removed ZenDistributor’s cart weight assistance.</li><li>Kept trader repairs available and set the hip lantern controls to K for light and Alt + K for heat.</li><li>Tuned the troll raid down: fewer trolls, no extra stars or modifiers, and an Elder progression requirement.</li></ul><p><a href="mods.html">Browse the complete mod list →</a></p></article><section class="band"><h2>Keeping everyone together</h2><p>Use the pack version announced in Discord. Any future update that needs extra installation steps will be called out here.</p></section>''')
page('auto-close-doors.html','Auto Close Doors',f'''<div class="eyebrow">True Bastards mods · Version 0.2.1</div><h1 class="page-title">Auto Close Doors</h1><p class="intro">Leave the door duty to the timer. Player-built doors and gates close automatically, with a preference chosen by the person who built them.</p><div class="actions"><a class="button" href="{DISCORD}">Get the pack on Discord ↗</a><a class="button secondary" href="mods.html">All mods</a></div><div class="grid"><section class="card"><h3>Your build, your choice.</h3><p>Choose a custom timer, follow the server default, or keep your doors open. Ordinary players can change their own settings.</p></section><section class="card"><h3>Gates included.</h3><p>Wooden gates and other player-built gates using normal door behaviour are included. Crypt doors and doors in generated buildings are left alone.</p></section><section class="card"><h3>Remembered for you.</h3><p>Your choice is saved per character and world on the server. It still applies while you are offline, whoever opens your door.</p></section></div><section id="settings"><h2>Choose your timer</h2><ol class="steps"><li>Join the server and allow your preferences to synchronize.</li><li>Open <strong>F1 → TrueBastards Auto Close Doors → 2 - My doors</strong>.</li><li>Choose a mode below. For a custom timer, select <strong>CustomTimer</strong> and set <strong>Custom delay seconds</strong>.</li></ol><table><thead><tr><th>Mode</th><th>What happens</th></tr></thead><tbody><tr><td>ServerDefault</td><td>Your doors follow the server’s current default.</td></tr><tr><td>CustomTimer</td><td>Your doors close after your chosen delay, from 1 to 3600 seconds.</td></tr><tr><td>NeverClose</td><td>Your doors remain open until someone closes them manually.</td></tr></tbody></table><p class="muted">Changing only the number while still in ServerDefault mode does not activate your personal timer.</p></section><section class="band"><h2>For example</h2><p>Beanie chooses NeverClose and SettDravan chooses 30 seconds. Beanie’s doors stay open; SettDravan’s doors close after 30 seconds—even when Beanie is the one opening them.</p></section><div class="split"><section><h2>How doors behave</h2><ul><li>Existing player-built doors work when they have a recorded builder.</li><li>Closing and reopening starts a new countdown.</li><li>Paired doors each follow their own builder’s preference.</li><li>Changing a timer applies to doors already open. A shorter delay may close an overdue door promptly.</li><li>Doors requiring keys or which cannot normally close are excluded.</li><li>Unloaded areas are not kept running. An overdue door can close when its area loads again.</li></ul></section><section class="card"><h3>Server controls</h3><p>Admins use <strong>1 - Server</strong> to enable or disable automatic closing globally and change the default delay.</p><p>The mod ships with a 60-second default, but the server can change it. A default of zero leaves ServerDefault doors open; a player’s custom timer can still apply while the feature is enabled.</p></section></div><section><h2>Installation and updates</h2><p>Included with the pack. Use the <a href="install.html#update">pack installation instructions</a>; no separate download is needed. The same door-mod version must be installed on the server and every client. The pack includes its BepInEx and Jötunn dependencies.</p></section><section class="band"><h2>If a door stays open</h2><ul><li>Check that the door was built by your character and that your mode is CustomTimer if you set a personal delay.</li><li>Check you installed the current pack/update and restarted Valheim.</li><li>Wait for your preferences to synchronize after joining. Settings made in the main menu are not submitted.</li><li>Admins may have disabled the feature globally.</li></ul><p>If it still does not close, tell us in <a href="{DISCORD}">Discord</a> which door, who built it and which mode you selected. Include your client log if possible.</p></section><section><h2>Latest change · 0.2.1</h2><p>Fixed the initial server handshake that could leave clients waiting for door preferences. Added clearer synchronization messages to help diagnose problems.</p></section>''')

page('progression-bridge.html','Progression Bridge',f'''<div class="eyebrow">True Bastards mods · Version 0.1.1</div><h1 class="page-title">Progression Bridge</h1><p class="intro">Connects Star Level System’s raid checks to the personal boss progression tracked by World Advancement Progression.</p><div class="actions"><a class="button" href="{DISCORD}">Get the pack on Discord ↗</a><a class="button secondary" href="mods.html">All mods</a></div><section class="band"><h2>Progress belongs to your character.</h2><p>Our pack tracks boss progress individually. The bridge lets Star Level System use the targeted character’s progression when checking which raids are eligible, including on a dedicated server where global boss keys are blocked.</p></section><div class="split"><section><h2>What it does</h2><ul><li>Uses the targeted character’s World Advancement Progression keys alongside world keys for Star Level System’s raid requirements.</li><li>Waits for a character’s progression data before deciding raid eligibility.</li><li>Includes personal WAP keys in Star Level System’s local personal-key queries.</li></ul><p>Raid chances, biome requirements and cooldowns still apply. The bridge does not force raids to start.</p></section><section class="card"><h3>A shared base is still shared.</h3><p>Eligibility can be personal, but spawned enemies exist in the world. Nearby players and shared buildings can still be caught up in someone else’s raid.</p></section></div><section><h2>No player setup needed</h2><p>The bridge comes with the pack and should stay installed on both clients and the server. There are no personal settings to change.</p><p>This version is designed for <strong>Star Level System 1.19.0</strong> and <strong>World Advancement Progression 1.0.0</strong>. Use the complete pack instead of independently updating those mods.</p></section><section><h2>What it leaves alone</h2><p>It does not grant boss kills, alter loot rewards, change creature statistics or adjust star chances. Raid configuration and your saved progression remain managed by their respective mods.</p></section><section class="band"><h2>Already defeated a boss before joining?</h2><p>The bridge does not convert earlier boss kills into WAP’s personal progress. If gear is blocked with “The Gods Reject You,” contact us in <a href="{DISCORD}">Discord</a> and explain which bosses that character has defeated. Restoring earlier progress is separate from this bridge.</p></section>''')


page('keybindings.html','Default Keybindings','''<div class="eyebrow">Keep this handy</div><h1 class="page-title">Default Keybindings</h1><p class="intro">The keyboard and mouse shortcuts supplied with the September 26 test pack. Your own remaps may differ. Most everyday Valheim controls stay in the game’s Settings → Controls menu.</p>
<h2>Everyday shortcuts</h2><table><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody>
<tr><td><kbd>F1</kbd></td><td>Open mod settings, including your personal door timer.</td></tr>
<tr><td><kbd>K</kbd></td><td>Toggle your equipped hip lantern’s light.</td></tr>
<tr><td><kbd>Left Alt</kbd> + <kbd>K</kbd></td><td>Toggle hip lantern heat.</td></tr>
<tr><td><kbd>I</kbd></td><td>Open your Adventure Backpack.</td></tr>
<tr><td><kbd>L</kbd></td><td>Toggle the Adventure Backpack wisplight, when available.</td></tr>
<tr><td><kbd>F6</kbd></td><td>Toggle first-person view.</td></tr>
<tr><td><kbd>G</kbd> / <kbd>H</kbd> / <kbd>J</kbd></td><td>Use Epic Loot ability slots 1, 2 and 3. Requires an equipped item granting an ability.</td></tr></tbody></table>
<p class="muted">Adventure Backpacks also has Y assigned to quick-drop, but the required Outward Mode is disabled in the pack.</p>
<h2>Building and organising</h2><table><thead><tr><th>Key</th><th>When to use it</th></tr></thead><tbody>
<tr><td><kbd>B</kbd></td><td>Equip or put away your best hammer from your inventory. Hold to select repair.</td></tr>
<tr><td><kbd>Left Shift</kbd> + <kbd>←</kbd> / <kbd>→</kbd></td><td>With a hammer equipped, cycle building rotation angles.</td></tr>
<tr><td><kbd>Left Alt</kbd></td><td>Hold while interacting with a double door to open or close only that door.</td></tr>
<tr><td><kbd>Q</kbd></td><td>Use the alternate action shown by supported Zen interactions. Follow the on-screen prompt.</td></tr>
<tr><td><kbd>Left Ctrl</kbd> + left click</td><td>With your hammer equipped, point at furniture, hold Ctrl and click to pick it up. Right-click cancels. Follow the placement prompts.</td></tr>
<tr><td>Middle mouse</td><td>ZenSign’s item search from the inventory.</td></tr>
<tr><td><kbd>Left Shift</kbd></td><td>Toggle camera focus on a ZenSign search result.</td></tr></tbody></table>
<h2>Move or resize the Daywheel</h2><p>Put your hammer, hoe or cultivator away, then press <kbd>F8</kbd> to enter the Daywheel’s move mode.</p><table><thead><tr><th>Control</th><th>In move mode</th></tr></thead><tbody><tr><td>Left mouse drag</td><td>Move the display.</td></tr><tr><td>Arrow keys</td><td>Nudge its position. Shift makes larger steps; Ctrl makes smaller steps.</td></tr><tr><td><kbd>Page Up</kbd> / <kbd>Page Down</kbd></td><td>Increase or decrease its size.</td></tr><tr><td><kbd>Home</kbd> / <kbd>End</kbd></td><td>Previous or next theme.</td></tr><tr><td><kbd>F8</kbd></td><td>Finish adjusting the display.</td></tr></tbody></table>
<section class="band"><h2>Make the controls yours</h2><p>Open F1 and find the relevant mod to change its available personal bindings. Server-controlled options may be locked. Use the game’s own controls menu for vanilla actions.</p><p>If one key triggers two things, rebind one of them. Epic Loot’s G ability is worth checking against your existing game controls. These are the supplied defaults, not a guarantee that every personal setup is conflict-free.</p><p><a href="auto-close-doors.html#settings">Set your door timer →</a></p></section>''')

page('backpack-balance.html','Backpack Balance','''<div class="eyebrow">True Bastards mods · Version 0.1.2</div><h1 class="page-title">Backpack Balance</h1><p class="intro">A sturdier journey for Jude’s backpacks. Their durability and armour now follow familiar cape tiers, while keeping their carrying bonuses.</p><table><thead><tr><th>Backpack</th><th>Matches</th></tr></thead><tbody><tr><td>Simple Backpack</td><td>Deer Hide Cape durability and armour, including upgrades.</td></tr><tr><td>Heavy Backpack</td><td>Troll Hide Cape durability and armour, including upgrades.</td></tr></tbody></table><section class="band"><h2>Already own one?</h2><p>The change applies automatically when the pack loads. Repair your backpack at a suitable station to fill its increased durability.</p></section><div class="split"><section><h2>What stays familiar</h2><p>Your backpack keeps its carrying bonus, weight, movement penalty and crafting recipe. The patch follows the matching cape’s stats; it does not add a new item or ask you to replace your existing backpack.</p></section><section class="card"><h3>Which backpacks?</h3><p>This covers the Simple Backpack and Heavy Backpack from Jude’s Equipment. Adventure Backpacks is a separate mod with its own bags and storage features.</p></section></div><section><h2>No setup needed</h2><p>Included in the September 26 test pack. Install the complete pack on your client; the server uses the matching version. There are no personal settings to adjust.</p><a href="install.html">Installation instructions →</a></section>''')
